-- 1) Sources
INSERT INTO sources (id, url, title, domain, source_type, accessed_at, is_official, is_verified, created_at) VALUES (3136, 'https://convocatorias.conicet.gov.ar/wp-content/uploads/sites/3/publico/convocatoria-becas-2026/becas-priorizadoslibres-2026/BASES-DOC-2026_6f469b3fa14a105255.pdf', 'Bases para el Concurso de Becas Internas Doctorales 2026 (official PDF) | CONICET Convocatorias', 'convocatorias.conicet.gov.ar', 'scholarship', now(), true, true, now()), (3137, 'https://www.gov.br/capes/pt-br/acesso-a-informacao/acoes-e-programas/bolsas/bolsas-no-pais', 'Programas Institucionais no Pais - Demanda Social, PROAP, PROEX (official) | CAPES', 'www.gov.br', 'scholarship', now(), true, true, now());

-- 2) 730 uplift (rel 8 -> 10): remove stale CNPq R$1,500/R$2,200 + importer GPA/IELTS minima; normalise award/deadline/status/documents/eligibility.
UPDATE scholarships SET provider = 'CAPES, CNPq and FAPESP (Brazilian federal/state research agencies) - quotas allocated by graduate programmes; verified at Unicamp', description = 'CAPES / CNPq / FAPESP graduate scholarships is not one central competition: it is the established record (verified at the University of Campinas, Unicamp) for how master''s and doctoral students at Brazilian public universities are funded. CAPES''s institutional programmes - Demanda Social (for CAPES-recognised programmes graded 3-5), PROEX (excellence programmes graded 6-7) and PROAP - distribute monthly scholarship quotas to universities, and each graduate programme''s committee allocates its quotas to admitted, full-time students by its own ranking; CNPq and, in Sao Paulo state, FAPESP fund additional quotas under their own rules and values. Because public universities such as Unicamp charge no tuition, the monthly bolsa is pure maintenance money. Monthly values are fixed in each agency''s current official table and are revised by portaria; the figures previously stored here (CNPq master''s R$1,500/month and doctorate R$2,200/month, read earlier from one Unicamp institute page) predate the agencies'' later revisions and have been removed - check the current CAPES/CNPq/FAPESP tables before budgeting. There is no separate scholarship application and no single national deadline: you apply to a graduate programme''s selection process, and funding follows the programme''s quota allocation. Foreigners should also know the dedicated federal channel for foreign graduate students, PEC-PG (CAPES with the Ministry of Foreign Affairs), which runs its own selection notices and is not covered by this record; day-to-day study and administration run in Portuguese.', requirements = 'Full-time admission to a CAPES-recognised stricto sensu graduate programme (master''s or doctorate) - allocation is by the programme committee''s ranking of admitted students against the CAPES/CNPq/FAPESP quotas it holds, so outcomes depend on programme, year and quota availability. Full-time dedicated study is the norm; each funding agency''s current rules govern dedication, whether paid work may be combined with the bolsa, duration limits and renewal reporting, and foreign holders must satisfy the agency and visa conditions in force - read the current agency and programme rules rather than relying on summaries. No agency-level GPA or English-test minimum exists (the previously stored GPA 3.0 / IELTS 6.5 figures were importer defaults and have been removed); selection criteria are each programme''s own, published in its selection notice (typically degree record and, for research degrees, a project proposal and interview). Instruction and administration are in Portuguese.', deadline = 'No single deadline: each graduate programme runs its own selection calendar (commonly one or two rounds a year) and allocates CAPES/CNPq/FAPESP quotas to admitted full-time students; agency quota rounds follow the academic year. Check the target programme''s current selection notice (Unicamp programmes publish theirs through the university''s graduate pages).', deadline_date = NULL, deadline_type = 'not_published', application_status = 'open', recurrence = 'annual', expected_opening_period = NULL, expected_deadline_period = NULL, rounds = '[{"name": "Graduate programme selection rounds (quota allocation)", "status": "Each CAPES-recognised programme sets its own selection calendar (commonly one or two rounds a year) and ranks admitted full-time students for its CAPES (Demanda Social/PROEX), CNPq and FAPESP quotas; no central scholarship deadline exists.", "deadline_date": null}]', eligible_countries = '["All - full-time students admitted to CAPES-recognised graduate programmes (verified at Unicamp); foreign holders follow the funding agencies current rules"]', award_amount = NULL, award_currency = 'BRL', award_period = 'month', award_basis = 'variable', funding_type = 'Monthly maintenance stipend (bolsa) paid from CAPES, CNPq or FAPESP quotas allocated by the graduate programme at the funding agency current table value; public-university tuition is not charged, so funding is living-cost money', tuition_coverage = 'Not applicable as a waiver: Brazilian public universities such as Unicamp do not charge tuition for regular graduate programmes; the bolsa covers living costs', living_allowance = NULL, travel_allowance = NULL, accommodation = NULL, required_documents = '["Application to the chosen graduate programmes selection process under its published notice (edital)", "Degree certificate(s) and transcripts as the programmes notice requires", "Research proposal / project where the programmes selection notice requires it", "Documents required by the funding agency on quota activation (per current CAPES/CNPq/FAPESP rules)"]', english_requirements = 'No agency-level English score. Graduate study and administration run in Portuguese; individual programmes set their own language rules in their selection notices.', min_gpa = NULL, min_ielts = NULL, website_url = 'https://www.gov.br/capes/pt-br/acesso-a-informacao/acoes-e-programas/bolsas/bolsas-no-pais', source_url = 'https://www.gov.br/capes/pt-br/acesso-a-informacao/acoes-e-programas/bolsas/bolsas-no-pais', verification_status = 'verified', source_reliability = 10, last_verified_at = now(), last_updated_at = now(), notes = 'Enrichment Batch 29 (2026-10-28) uplift from rel 8 to rel 10: removed stale stored CNPq rates (R$1,500 master''s / R$2,200 doctorate per month, read earlier from one Unicamp institute page; superseded by later agency revisions - current agency table values intentionally NOT encoded, they change by portaria) and importer GPA 3.0 / IELTS 6.5 minima (plus the IELTS english_requirements text); normalised award (BRL month variable), deadline (not_published + rounds), status open, required documents and eligibility; empty-string accommodation cleared. Mechanism re-verified first-hand from CAPES institutional-programmes page (source 3137: Demanda Social for programmes graded 3-5, PROEX for grades 6-7, PROAP), fetched 2026-10-28; a Unicamp PRPG bolsas slug fetched the same day returned 404 after the site migration, so the Unicamp international-office application URL is retained from the 2026-10-23 verification (university 246) and catalogue row us 217 was rewritten from stale ENEM-era text. PEC-PG (CAPES/MRE foreigner channel) is mention-only and unevaluated as a separate record. Rel 10; university backlink retained.' WHERE id = 730;

-- 3) NEW 991 CONICET Beca Interna Doctoral (reuses source 3135 from Pass 122; bases = 3136)
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, degree_levels, eligible_majors, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, eligible_countries, funding_type, tuition_coverage, living_allowance, travel_allowance, accommodation, application_fee, english_requirements, required_documents, application_url, opening_date, deadline_date, deadline_type, deadline_range_start, deadline_range_end, rounds, recurrence, expected_opening_period, expected_deadline_period, application_status, last_verified_at, last_updated_at, verification_status, source_reliability, source_url, notes, is_active, university_id, award_amount, award_currency, award_period, award_basis) VALUES (991, 'Beca Interna Doctoral (CONICET Doctoral Fellowship)', 'Consejo Nacional de Investigaciones Cientificas y Tecnicas (CONICET) - Argentina', 'Argentina', 'Living Stipend', 0, 'Annual competition. The 2026 call ran 27 July - 21 August 2026 via SIGEVA-CONICET (submission deadlines staggered 18-21 August by the last digit of the identity document), for fellowships starting 1 April 2027; the next annual call is expected around late July-August 2027 under the same pattern. Watch the official CONICET calls portal.', '["PhD"]', '["All Majors"]', NULL, NULL, false, true, 'Argentina''s main federal doctoral-training fellowship, run by the national research council CONICET in an annual national competition (about 1,000 new Beca Interna Doctoral fellowships were foreseen in the 2026 call). It pays a monthly stipend (estipendio) for 60 months of full-time research training - basic research, applied research or technological development - leading to a doctorate at an Argentine university or research institute, under a named director at their usual workplace. It is expressly open to graduates of Argentine or foreign universities: the official 2026 rules even provide for foreign winners living abroad, who must enter Argentina with the proper immigration status (not as tourists) - though CONICET does not fund travel, immigration fees or relocation. It is a training fellowship, not employment: it creates no employment relationship and carries no pension contributions, and it excludes training for the liberal professions and artistic creation. Allocation is by discipline commissions, with 70% of each commission quota going to prioritised topics/regions and 30% by merit order. Sister lines in the same call - Beca Interna de Finalizacion de Doctorado (24 months) and Beca Interna Postdoctoral (36 months), plus co-funded variants - exist but are not covered by this record. The official rules fetched for this record do not state the stipend amount (stipends are set under CONICET fellowship regulations and resolutions), so no ARS figure is encoded - check the current amount on the CONICET site.', 'From the official 2026 bases: graduates of Argentine or foreign universities (final-year students may apply with at most 5 undergraduate subjects outstanding, but must have graduated before the fellowship starts); no age limit. You propose an original research plan of at most 5 pages, written in Spanish only (plans in other languages are rejected), supervised by a named director (and codirector where required) - directors may be CONICET career researchers or equivalently qualified researchers at other institutions, may supervise at most 3 early-stage internal doctoral fellows at once, and may not be related to you within the 3rd degree; current CONICET fellows cannot be directors. The doctorate must be accredited by CONEAU (or submitted for accreditation). Only one application per candidate across CONICET fellowship categories and calls. People who have already held a doctoral fellowship funded by CONICET or any other institution, national or foreign, cannot apply to this category (they may seek the Finalizacion line instead). Applications are electronic only, through SIGEVA-CONICET after registering on the CONICET Intranet, with deadlines staggered by the last digit of your identity document. If you win: exclusive dedication to the work plan (limited paid teaching, or up to 12 hours/week of public-health shifts with authorisation, may be added under the fellowship regulations); daily work at the director workplace with certified attendance; no change of workplace or director in the first year; proof of starting doctoral enrolment within 6 months and of admission by month 36, or the fellowship lapses.', 'https://convocatorias.conicet.gov.ar/becas/convocatoria-vigente/', '["All - graduates of Argentine or foreign universities (foreign winners living abroad must enter Argentina with the proper immigration status, not as tourists; CONICET funds no travel, immigration or relocation)"]', 'Monthly research-training stipend (estipendio) for 60 months under CONICET fellowship regulations; not an employment contract and carries no pension contributions', 'Not a tuition instrument: the beca pays a monthly stipend for full-time doctoral research training; doctoral programme fees where charged, and travel/immigration costs, are not covered by CONICET', NULL, NULL, NULL, NULL, 'No English test appears in the official 2026 bases; applications and work plans are accepted in Spanish only (plans in other languages are rejected).', '["Electronic application via SIGEVA-CONICET (CONICET Intranet registration; endorsements attached digitally)", "Official analytic certificate / academic history showing passed and failed subjects and the personal average", "Original research plan of at most 5 pages, in Spanish, endorsed by the proposed director (and codirector where required)", "Proposed CONEAU-accredited (or accreditation-submitted) doctorate and workplace", "(After award) proof of starting doctoral enrolment within 6 months and of admission by month 36"]', 'https://convocatorias.conicet.gov.ar/becas/convocatoria-vigente/', NULL, NULL, 'not_published', NULL, NULL, '[{"name": "Convocatoria 2026 (closed)", "status": "Applications via SIGEVA 27 Jul-21 Aug 2026, staggered by identity-document last digit (18-21 Aug); about 1,000 internal doctoral fellowships foreseen, 60 months from 1 Apr 2027; 70% of quotas to prioritised topics/regions, 30% by merit order.", "deadline_date": null}, {"name": "Annual pattern", "status": "Calls are annual in the July-August window for an April start; the portfolio also includes Finalizacion de Doctorado (24 months) and Postdoctoral (36 months) lines plus co-funded variants, not covered by this record.", "deadline_date": null}]', 'annual', 'Late July', 'Mid-to-late August (staggered by last digit of identity document)', 'upcoming', now(), now(), 'verified', 10, 'https://convocatorias.conicet.gov.ar/wp-content/uploads/sites/3/publico/convocatoria-becas-2026/becas-priorizadoslibres-2026/BASES-DOC-2026_6f469b3fa14a105255.pdf', 'Enrichment Batch 29 (2026-10-28) candidate add - CONICET Beca Interna Doctoral taken up as its own record after Pass 122 retired the invented-name composite 400 that pointed at this scheme. Evidence fetched first-hand 2026-10-28: CONICET Convocatoria 2026 page chunks 0-1 (source 3135, created in Pass 122 and reused: 1,000 doctoral fellowships foreseen; window 27 Jul-21 Aug 2026 via SIGEVA; 60 months from 2027-04-01; 70/30 prioritised/merit allocation; Finalizacion 24 months and Postdoctoral 36 months siblings; co-funded windows) and the official Bases Becas Internas Doctorales 2026 PDF chunks 0-1 of 3 (source 3136: open to graduates of Argentine OR foreign universities; foreign winners abroad must complete the immigration procedure - no pudiendo hacerlo como turistas; CONICET funds no travel/immigration/relocation; 60 months non-renewable; enrolment proof by month 6 and admission by month 36; no age limit; no employment relationship or pension contributions; exclusive dedication with limited teaching/health-shift add-ons; Spanish-only plans of at most 5 pages; director caps/kinship/CONEAU rules; prior doctoral-fellowship holders barred; SIGEVA-only, deadlines staggered 18-21 Aug 2026 by identity-document last digit). Evaluation-criteria detail in PDF chunk 2 not read; no stipend ARS amount appears in the fetched bases, so none is encoded (ARS month variable). Status upcoming/not_published because the 2026 call is closed and 2027 dates are unpublished. No university backlink (workplace is applicant-proposed across Argentine institutions); no university_scholarships row. Rel 10.', true, NULL, NULL, 'ARS', 'month', 'variable');

