-- 5) us 217 rewrite (Unicamp catalogue row; stale ENEM/Vestibular-era text)
UPDATE university_scholarships SET scholarship_name = 'CAPES / CNPq / FAPESP graduate scholarships', availability_status = 'available', funding_type = 'Merit-based', max_scholarship = 'Monthly stipend at the funding agency current table value (CAPES/CNPq/FAPESP quota)', covers_tuition = false, covers_living_expenses = true, valued_aspect = 'Graduate programme selection ranking and quota allocation', eligibility_notes = 'Unicamp is a public university and charges no tuition. Master''s and PhD students admitted full-time compete for monthly CAPES, CNPq and FAPESP stipend quotas that each graduate programme committee allocates by its own ranking; there is no central international scholarship and no single deadline - you enter through the programme''s own selection process. Monthly values are set in each agency''s current official table (figures previously shown here were superseded). Study and administration run in Portuguese; no agency-level GPA or English-test minimum applies. Rewritten 2026-10-28 (Batch 29) from the stale ENEM/Vestibular-era catalogue text.', official_url = 'https://www.internationaloffice.unicamp.br/en/estrangeiros/estudantes-estrangeiros/formas-de-ingresso/', source_url = 'https://www.internationaloffice.unicamp.br/en/estrangeiros/estudantes-estrangeiros/formas-de-ingresso/', verification_status = 'verified', last_verified_at = now() WHERE id = 217;

